from h import *
R(9277390,"فطر البورتوبيلو النباتي المحشو بنكهة اللازانيا",
"فطر بورتوبيلو نباتي محشو بحشوة ريكوتا السبانخ بنكهة \"الجبن\" وتعلوه صلصة بولونيز غنية، لتشبع رغبتك في تناول اللازانيا.",
"6 حصص","حصة واحدة",
["6 حبات فطر بورتوبيلو منظّفة بالفرشاة","1½ كوب كاجو نيء","1 ملعقة كبيرة خل التفاح","¼ كوب خميرة غذائية","¼ ملعقة صغيرة مسحوق الثوم","¾ ملعقة صغيرة ملح البحر","½ كوب ماء","عبوة سبانخ صغيرة (بيبي) وزنها 5 أونصات، أي حوالي 3-4 حفنات كبيرة أو 1 كوب سبانخ مذبلة","1 كوب صلصة طماطم أو صلصة المارينارا المفضلة لديك","½ كوب جوز مفروم","¼ ملعقة صغيرة ملح البحر","¼ ملعقة صغيرة ريحان مجفف","¼ ملعقة صغيرة أوريجانو مجفف","¼ ملعقة صغيرة مسحوق الثوم","جبن بارميزان نباتي","بقدونس طازج"],
["سخّن الفرن مسبقًا على 400° فهرنهايت (200° مئوية) وبطّن صينية خبز كبيرة بورق الزبدة.","نظّف الفطر بالفرشاة واكشط الشرائح الداخلية (الخياشيم) بملعقة صغيرة معدنية. احرص على عدم كسر الفطر. ثم ضعه على الصينية وجانب الساق لأسفل. رشّ الوجه العلوي بالملح والفلفل واخبزه لمدة 10 دقائق. تسمح هذه الخطوة بخروج جزء من الرطوبة من الفطر حتى لا يصبح مائيًا لاحقًا.","في هذه الأثناء، قلّب السبانخ في مقلاة أو وعاء على نار متوسطة حتى تذبل. أضف قطرة أو قطرتين من الماء إذا لزم الأمر لتبدأ العملية. قلّب باستمرار لمنع الالتصاق. وبعد أن تذبل، اعصرها لإخراج أكبر قدر ممكن من السائل باستخدام منشفة مطبخ نظيفة أو كيس حليب المكسرات أو منديل ورقي. ضعها جانبًا.","ضع مكونات جبن الريكوتا في محضّر الطعام ما عدا السبانخ. اخلطها حتى تصبح ناعمة، مع كشط الجوانب عند الحاجة. وبعد أن تصبح ناعمة، أضف السبانخ وقلّب بالنبض 3-4 مرات حتى تمتزج. لا تفرط في الخلط وإلا اخضرّ لون الجبن.","بعد ذلك، اخلط جميع مكونات صلصة البولونيز في وعاء صغير. قلّب وضعها جانبًا.","أخرج الفطر من الفرن واقلبه بحيث يصبح جانب الساق لأعلى. امتصّ الرطوبة الزائدة بتجفيف الفطر بمنشفة مطبخ نظيفة أو منديل ورقي.","وزّع الريكوتا على حبات الفطر الست. ثم ضع على كل واحدة منها صلصة البولونيز. اخبز الفطر المحشو لمدة 10-12 دقيقة، ثم أخرجه من الفرن وقدّمه مع البقدونس الطازج وفلاكس الفلفل الأحمر و/أو جبن البارميزان النباتي."],
["إذا لم يكن لديك محضّر طعام قوي، فانقع الكاجو في ماء شديد السخونة لمدة 15-30 دقيقة، ثم صفّه قبل تحضير جبن الريكوتا.","إذا كنت تستخدم سبانخ مجمدة، فقس حوالي 1 كوب وأذبها واعصرها لإخراج أكبر قدر ممكن من الرطوبة باستخدام كيس حليب المكسرات أو قطعة قماش أو مناديل ورقية.","لا تفرط في خلط السبانخ عند تحضير الريكوتا. يكفي أن تقلّب بالنبض بضع مرات لتمتزج. فأنت تريد أن ترى خيوطًا من السبانخ في الريكوتا، لا جبنًا أخضر اللون.","لتحويلها إلى مقبلات، استخدم من مرتين إلى 3 مرات العدد نفسه من أغطية الفطر أو فطر كريميني، بحسب حجمه.","إذا كنت تخطط مسبقًا، فحضّر جبن الريكوتا وصلصة البولونيز واحفظهما في الثلاجة منفصلين لمدة 2-3 أيام مقدمًا. ثم احشُ الفطر واخبزه يوم التقديم.","تبقى الأطعمة المتبقية صالحة في الثلاجة لمدة 2-3 أيام في وعاء محكم الإغلاق."],
{"For the Ricotta":"للريكوتا","For the Bolognese Sauce":"لصلصة البولونيز","Optional Garnish":"للتزيين (اختياري)"})
R(9279723,"غموس السبانخ والخرشوف النباتي [خالٍ من الزيت]",
"غموس سبانخ وخرشوف نباتي كريمي وذائب ولذيذ للغاية! هذه المقبلات الممتعة مطاطية وطرية لدرجة أن أحدًا لن يصدق أنها نباتية.",
"8 حصص","حصة واحدة",
["2 حفنة كبيرة من السبانخ الطازجة أو 2 كوب سبانخ مجمدة*","علبة قلوب خرشوف في الماء وزنها 13.5 أونصة، غير متبّلة (حوالي 1½ كوب)","1 كوب كاجو نيء","2 كوب ماء","⅓ كوب خميرة غذائية","½ كوب نشا التابيوكا أو دقيق التابيوكا","3 فصوص ثوم مقشّرة","1 ملعقة كبيرة خل أبيض","1½ ملعقة صغيرة ملح البحر","¾ كوب حليب الكاجو غير المحلى أو حليب نباتي من اختيارك","جبن بارميزان نباتي"],
["صفّ الخرشوف واشطفه ثم قطّعه إلى شرائح رفيعة وضعه جانبًا.","ضع جميع المكونات في خلاط عالي السرعة ما عدا الخرشوف والسبانخ. اخلط حتى يصبح الخليط ناعمًا، وسيكون سائلًا جدًا لكنه سيتكاثف عند الطهي.","اسكب الخليط في مقلاة غير لاصقة، أو استخدم مقلاة تصلح للفرن مثل مقلاة الحديد الزهر إذا أردت تحمير الغموس لاحقًا. أضف شرائح الخرشوف والسبانخ إلى المقلاة. اطهِ على نار متوسطة مع التقليب باستمرار لمدة 5 دقائق تقريبًا حتى يصبح الخليط سميكًا ويغلي.","اختياري: اضبط الفرن على الشواء العالي (برويل). ثم انقل الغموس إلى طبق يصلح للفرن (إن لم يكن فيه بالفعل). حمّره لمدة 2-5 دقائق حتى يصبح وجهه ذهبيًا ويغلي. راقبه بعناية لمنع احتراقه. ثم أخرجه من الفرن.","رشّ عليه جبن البارميزان النباتي إن رغبت. ثم قدّمه دافئًا مع رقائق التورتيلا أو البسكويت المالح أو الخضار النيئة أو الخبز أو أي أصناف أخرى تحب غمسها."],
["* إذا كنت تستخدم سبانخ مجمدة، فتأكد من عصرها وتصفيتها من الماء قدر الإمكان قبل إضافتها إلى المقلاة. إذا لم يكن لديك خلاط عالي السرعة، فانقع الكاجو أولًا في ماء شديد السخونة لمدة 15-30 دقيقة، ثم صفّه واستخدمه حسب التعليمات. سيساعد ذلك على تليينه وسهولة خلطه. إذا أصبح الغموس سميكًا جدًا، فأضف مزيدًا من الحليب أو الماء إلى المقلاة لتخفيفه. لاحظ أنه يتصلب عندما يبرد، وأن إعادة تسخينه تعيد إليه قوامه الحريري. للحصول على نكهة أعمق، استخدم مرق الخضار بدلًا من الماء. لجعله حارًا، أضف ½ ملعقة صغيرة من الفلفل الحار (كايين) أو 1-2 ملعقة صغيرة من الصلصة الحارة المفضلة لديك. للحصول على غموس بنكهة مدخنة، أضف 1 ملعقة صغيرة من البابريكا المدخنة. للتحضير المسبق، اخلط وأطهِ على الموقد حسب التعليمات ثم احفظه في الثلاجة حتى الحاجة. ثم ضعه في الفرن على 350° فهرنهايت (175° مئوية) لتسخينه جيدًا لمدة 10-15 دقيقة. ثم حمّره لمدة 2-5 دقائق إضافية ليحمرّ وجهه، إن أردت. احفظ الباقي في الثلاجة في وعاء محكم الإغلاق لمدة 3-4 أيام أو جمّده في وعاء مناسب للتجميد محكم الإغلاق لمدة تصل إلى 3 أشهر. الوصفة مستوحاة من وصفة الموزاريلا النباتية الخاصة بي."],
{"Optional Garnish":"للتزيين (اختياري)"})
R(9279842,"بطاطس مقلية نباتية محمّلة بالإضافات",
"استعد للاستمتاع بأشهى بطاطس مقلية نباتية محمّلة بالإضافات!",
"6 حصص","حصة واحدة",
["3 أرطال بطاطس روسيت","2 ملعقة كبيرة مرق خضار أو زيت أفوكادو","½ ملعقة صغيرة ملح البحر أو حسب الرغبة","1 وصفة من صلصة الجبن الخالية من المكسرات أو الجبن النباتي الذي تفضله","½ كوب فاصولياء حمراء","½ كوب زيتون أسود","½ كوب ذرة","1 حبة طماطم مقطعة مكعبات","1-2 بصل أخضر مقطع شرائح","1-2 فلفل هالبينو مقطع شرائح، اختياري","كريمة الكاجو","جواكامولي","صلصة سالسا"],
["سخّن الفرن مسبقًا على 425° فهرنهايت (220° مئوية) بوضع التحميص بالهواء الساخن وبطّن صينية خبز كبيرة بورق الزبدة.","قشّر البطاطس أو افركها جيدًا ثم قطّعها إلى أصابع باستخدام قطّاعة البطاطس أو سكين حادة. اخلطها مع المرق أو الزيت والملح. ثم رتّبها في طبقة واحدة على الصينية. حمّصها لمدة 20 دقيقة، ثم اقلبها وواصل التحميص 10-15 دقيقة أخرى، أو حتى تصل إلى درجة القرمشة المطلوبة.","في هذه الأثناء، حضّر صلصة الجبن وجهّز بقية الإضافات أثناء طهي البطاطس.","التقديم: استخدم طبق تقديم كبيرًا أو الصينية نفسها التي خبزت عليها. ابدأ بالبطاطس، ثم أضف نحو نصف صلصة الجبن، ثم انثر بقية الإضافات بأي ترتيب تحبه. وأخيرًا، أنهِ الطبق برشّ بقية صلصة الجبن فوقه وقدّمه."],
["رتّب البطاطس في طبقة واحدة مع ترك مسافة بين القطع للحصول على أكثر بطاطس مخبوزة قرمشة ولمنع الالتصاق. إذا كان فرنك بدون هواء ساخن، فتوقع وقت طهي أطول قليلًا. واصل الخَبز حتى تصل إلى درجة القرمشة المطلوبة."],
{"For the Fries":"للبطاطس","For the Toppings":"للإضافات","For Dipping (optional)":"للغمس (اختياري)"})
R(9289404,"كوكيز هالوين صحية [لن يعرف أحد!]",
"كوكيز الهالوين الصحية هي الحلوى المثالية لإرضاء الأطفال والكبار على حد سواء!",
"26 قطعة كوكيز","حصة واحدة",
["1½ كوب حمص مطبوخ أو معلب","2 موزة متوسطة ناضجة (وزنها 230 جرامًا بالقشر)","¼ كوب شراب القيقب","½ كوب زبدة الفول السوداني، منزلية أو من المتجر (أو استبدلها بزبدة الصويا لتكون خالية من المكسرات)","2 ملعقة كبيرة صلصة التفاح غير المحلاة","1 كوب شوفان مجروش (خالٍ من الغلوتين إن أردت)","3 حفنات كبيرة من السبانخ الصغيرة (بيبي)","1 ملعقة صغيرة بيكنج باودر","رقائق الشوكولاتة أو عيون حلوى"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (175° مئوية) وبطّن صينيتي خبز بورق الزبدة.","ضع كل شيء في محضّر الطعام ما عدا المكونات الاختيارية واخلط حتى يصبح الخليط ناعمًا.","استخدم مغرفة كوكيز صغيرة لوضع العجين على صينيتي الخبز. ستحصل على حوالي 26 قطعة. ثم بيدين مبللتين قليلًا أو بظهر ملعقة اضغط على الكوكيز وشكّلها على هيئة دوائر. لا ينتشر العجين كثيرًا، لذا شكّله قبل الخَبز.","اختياري: إذا كنت تستخدم رقائق الشوكولاتة للعيون، فأضفها الآن إلى الكوكيز. أما إذا كنت تستخدم عيون الحلوى، فأضفها بعد الخَبز.","اخبز لمدة 16-18 دقيقة، ثم أخرج الكوكيز من الفرن واضغط عيون الحلوى (إن استخدمتها) برفق على الكوكيز وهي لا تزال دافئة. ولعمل الأفواه، استخدم عود أسنان أو طرف ملعقة أو شوكة لرسم أشكال مختلفة للأفواه على كل كوكيز مخيف. ثم اتركها لتبرد."],
["استخدم موزًا ناضجًا جدًا عليه بقع بنية، فلا توجد حلاوة مضافة كثيرة.","إذا كنت تستخدم عيون الحلوى، فاضغطها على الكوكيز مباشرة بعد إخراجه من الفرن وهو لا يزال دافئًا.","اصنع أشكالًا ممتعة للأفواه على الكوكيز الأخضر وهو لا يزال دافئًا. استخدم عود أسنان أو طرف ملعقة أو شوكة."],
{"Optional":"اختياري"})
R(9291733,"سلطة كول سلو نباتية خالية من الزيت",
"سلطة كول سلو نباتية كريمية ولذيذة، مقرمشة وحامضة قليلًا وغنية جدًا بالنكهة.",
"8 حصص","حصة واحدة",
["2 رطل ملفوف أحمر (بنفسجي)، حوالي 6-7 أكواب مبشور","2 حبة جزر كبيرة، حوالي 1-2 كوب مبشور","1 كوب مايونيز نباتي منزلي خالٍ من الزيت أو من المتجر","1½ ملعقة كبيرة شراب القيقب أو دبس التمر","1½ ملعقة كبيرة خل أبيض","1 ملعقة كبيرة خردل أصفر","¼ ملعقة صغيرة فلفل أسود"],
["بشّر الملفوف والجزر وضعهما في وعاء كبير.","في وعاء صغير، اخلط المايونيز وشراب القيقب والخل والخردل والفلفل الأسود. اخفق حتى يمتزج. ثم اسكب الصلصة على السلطة وقلّب حتى تتغطى بالتساوي."],
["للحصول على سلطة خالية من الزيت، استخدم مايونيز بذور القرع (البيبيتا) الخاص بي في هذه الوصفة. فالمايونيز الجاهز يحتوي عادةً على كمية كبيرة من الزيت.","لخيار بدون مايونيز، جرّب سلطة الكول سلو بصلصة الفول السوداني الخاصة بنا.","استخدم كول سلو مبشورًا جاهزًا من المتجر لتحضير أسرع. استخدم 6-8 أكواب من الخليط الذي تفضله.","تذوّق الصلصة قبل سكبها على السلطة وعدّل التتبيل إذا لزم الأمر. فأنت تريد صلصة ذات نكهة قوية لأن الخضار غير متبّلة.","بالنسبة للسلطة، أفضّل الملفوف الأحمر لما فيه من لون زاهٍ، ولكن يمكنك استخدام الملفوف الأخضر أو مزيجًا من النوعين إن أردت. ومن الإضافات الأخرى البقدونس والكزبرة الخضراء والكرفس والبصل الأخضر أو البصل الأحمر.","بالنسبة للصلصة، يمكنك إضافة مزيد من التوابل إن أردت. ومن الخيارات بذور الكرفس والكمون ومسحوق الفلفل الحار ومسحوق الثوم والبابريكا المدخنة أو الفلفل الحار (كايين).","طعم كول سلو النباتي هذا أفضل في اليوم نفسه الذي يُحضَّر فيه، ومع ذلك يمكن حفظ الباقي في الثلاجة لمدة تصل إلى 3 أيام.","تتضمن المعلومات الغذائية مايونيز بذور القرع (البيبيتا) الخاص بي. وإذا استبدلته بمايونيز جاهز من المتجر، فسيزيد ذلك من السعرات الحرارية والدهون."])
R(9293583,"أصابع الجزر المقلية بقلاية الهواء [خالية من الزيت]",
"بديل صحي للبطاطس المقلية يرضي رغبتك بجزء بسيط من السعرات الحرارية والدهون! لا حاجة إلى الزيت لتحضير أصابع الجزر المقرمشة بقلاية الهواء، وهي مليئة بالنكهة الرائعة.",
"حصتان","حصة واحدة",
["1 رطل جزر، حوالي 3 حبات جزر متوسطة/كبيرة","1 ملعقة كبيرة نشا التابيوكا (يُعرف أيضًا بدقيق التابيوكا)","½ ملعقة صغيرة ملح البحر","½ ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة زعتر مجفف، اختياري","1-2 ملعقة كبيرة بارميزان نباتي، اختياري","خردل بالعسل النباتي","مايونيز السريراتشا"],
["قشّر الجزر وقطّعه إلى أعواد بطول 4 بوصات وبسمك ¼ بوصة تقريبًا ليستوي بالتساوي.","ضع أصابع الجزر وجميع المكونات المتبقية في وعاء خلط متوسط وقلّب حتى تتغطى بالتساوي، ثم رتّبها في سلة القلاية في طبقة متساوية. (يمكن أن تتراكب فوق بعضها.)","اقلِ بالهواء الساخن على 400 درجة فهرنهايت (205 درجات مئوية) لمدة 15-20 دقيقة حتى تصل إلى درجة القرمشة المطلوبة، مع التقليب مرة واحدة عند منتصف المدة.","سخّن الفرن مسبقًا على 450 درجة فهرنهايت (230 درجة مئوية) وبطّن صينية خبز كبيرة بورق الزبدة.","أضف نشا التابيوكا والملح ومسحوق الثوم ومسحوق البصل والزعتر إلى الوعاء وقلّب حتى يتغطى كل الجزر بالتساوي. ثم افرد الجزر في طبقة واحدة على الصينية المجهزة مع ترك مسافة بين القطع حتى لا تتراكب.","اخبز لمدة 20 دقيقة، ثم أخرج الصينية من الفرن واقلب أصابع الجزر ورشّ عليها جبن البارميزان النباتي. أعدها إلى الفرن لمدة 10 دقائق أخرى، أو حتى تصل إلى درجة القرمشة المطلوبة."],
["حاول قدر الإمكان تقطيع أصابع الجزر بحجم متساوٍ ليستوي بالتساوي. اختر جزرًا متساوي العرض من أعلاه إلى أسفله إن أمكن. يختلف وقت الطهي بحسب الطريقة المستخدمة (الخَبز في الفرن أو القلي بالهواء) وبحسب حجم أصابع الجزر. يمكنك تحضير الجزر قبل يوم واحد كحد أقصى وحفظه في الثلاجة داخل الوعاء مع التوابل حتى وقت الخَبز. إذا لم تجد نشا التابيوكا أو دقيقها، فيمكنك استبداله بنشا الذرة وستحصل على نتائج مماثلة. طعم هذا الجزر أفضل عندما يكون مخبوزًا طازجًا، لكن يمكنك حفظ الباقي في الثلاجة لمدة تصل إلى 3 أيام."],
{"Air Frying Instructions":"طريقة القلي بالهواء","Oven Instructions":"طريقة الفرن","Dip for serving (optional)":"للغمس عند التقديم (اختياري)"})
R(9295060,"سلطة البطاطس والهليون",
"سلطة البطاطس والهليون الزاهية هذه احتفاء مثالي بنكهات الربيع!",
"6 حصص","حصة واحدة",
["2 رطل بطاطس صغيرة مفركة ومنظّفة (استخدمت مزيجًا من الحمراء والصفراء)","1 رطل هليون بعد قص الأطراف، ومقطع إلى قطع بطول 1 بوصة","1 كوب بازلاء مجمدة","2-3 ملاعق كبيرة بصل أحمر مقطع مكعبات","¼ كوب عصير ليمون","1 ملعقة كبيرة طحينة أو زبدة اللوز","1 ملعقة كبيرة شراب القيقب","1 ملعقة صغيرة خردل أصفر","1 ملعقة صغيرة مسحوق الثوم","1 ملعقة صغيرة أوريجانو مجفف","¼ كوب ثوم معمر (شيف) طازج مفروم ناعمًا","ملح + فلفل حسب الرغبة"],
["اغلِ قدرًا كبيرًا من الماء المملح.","أضف البازلاء والهليون واطهها لمدة 2-3 دقائق. ثم أخرجها بملعقة مثقبة وانقلها إلى وعاء خلط كبير.","بعد ذلك، أضف البطاطس الصغيرة واطهها حتى تلين عند غرزها بالشوكة، أي حوالي 15-20 دقيقة. صفّها واشطفها حتى تبرد بما يكفي للتعامل معها.","بينما تُطهى البطاطس، ضع مكونات الصلصة في وعاء صغير أو برطمان وامزجها جيدًا. إذا لزم الأمر، أضف بضع قطرات من الماء لتخفيف الصلصة.","قطّع البطاطس المطبوخة إلى نصفين (أو أرباع إذا كانت كبيرة) وأضفها مع البصل الأحمر إلى وعاء البازلاء والهليون. ثم أضف الصلصة وقلّب حتى تتغطى بالتساوي."],
["تذوّق الصلصة للتأكد من الملح والفلفل قبل خلطها مع السلطة. عدّل التتبيل إذا لزم الأمر.","يمكنك تحضير سلطة البطاطس والهليون هذه مسبقًا وحفظها في الثلاجة لمدة 1-2 يوم قبل التقديم."],
{"For the potato salad":"لسلطة البطاطس","For the dressing":"للصلصة"})
R(9296884,"شوربة القرنبيط المحمّص",
"شوربة القرنبيط المحمّص هذه غنية ومخملية وسهلة التحضير بشكل مدهش.",
"4 حصص","حصة واحدة",
["6 أكواب زهيرات قرنبيط (حوالي رأس قرنبيط متوسط واحد)","1 حبة بصل أصفر (مقطعة أرباعًا)","3 فصوص ثوم (مع ترك القشر)","4 أكواب مرق خضار قليل الصوديوم","1 ملعقة كبيرة معجون الميسو الأبيض","⅓ كوب خميرة غذائية","1-2 ملعقة كبيرة عصير ليمون (ابدأ بملعقة واحدة)","15 أونصة فاصولياء كانيليني بيضاء (مصفّاة + مشطوفة)","ملح وفلفل (حسب الرغبة)"],
["سخّن الفرن مسبقًا على 425° فهرنهايت (220° مئوية) بوضع التحميص بالهواء الساخن وبطّن صينية خبز كبيرة بورق الزبدة.","قطّع القرنبيط إلى زهيرات صغيرة لينضج بسرعة. قطّع البصل أرباعًا واترك القشر على الثوم. رتّبها في طبقة واحدة على صينية الخبز وحمّصها لمدة 20 دقيقة، أو حتى تحمرّ وتصبح ذهبية.","بعد التحميص، انقل الخضار وجميع المكونات المتبقية إلى الخلاط، على دفعات إذا لزم الأمر. اهرس الشوربة حتى تصبح ناعمة، لكن احتفظ بقطع قليلة من القرنبيط لتزيين الأطباق إن أحببت."],
[])
